def remove_consecutive_duplicates(lst):
    if not lst:
        return []

    result = [lst[0]]
    for i in range(1, len(lst)):
        # Only append if the current element is different from the last one added
        if lst[i] != result[-1]:
            result.append(lst[i])
    return result

